UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong><u>CÉDULA DE NOTIFICACIÓN - LEY NACIONAL DE TRÁNSITO </u></strong><strong><u>N°</u></strong><strong><u> 24.449</u></strong></p><p style="text-align:center"><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]   -   Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:justify"><strong><u>DATOS DEL INFRACTOR</u></strong></p><p style="text-align:justify"><strong>Señor/a:</strong><strong>   </strong>[Acta:Titular]</p><p style="text-align:justify"><strong>Domicilio:</strong><strong>   </strong>[Acta:Calle]<strong>   </strong><strong>N°</strong><strong> </strong><strong>  </strong> [Acta:Nro.Puerta]  </p><p style="text-align:justify"><strong>Localidad y Partido:</strong><strong>   </strong>[Acta:Localidad]  / [Acta:Partido]   <strong>Provincia</strong><strong>:  </strong>[Acta:Provincia.Infractor]</p><p style="text-align:justify"><strong><u>DIA Y HORA DE INFRACCIÓN / LUGAR DE INFRACCIÓN / DATOS DEL VEHÍCULO / DISPOSICIÓN LEGAL INFRINGIDA</u></strong></p><p style="text-align:justify"><strong>Fecha de la infracción: </strong><strong>  </strong> [Acta:Fecha]     <strong>Hora de la infracción: </strong><strong>   </strong>[Acta:Hora]   Hs.</p><p style="text-align:justify"><strong>Lugar de la infracción:</strong>   [Acta:Calle.Infraccion]   <strong>Ciudad</strong><strong>: </strong> [Acta:Localidad_Infraccion]   <strong>Partido:   </strong>MALVINAS ARGENTINAS   <strong>Provincia:   </strong>BUENOS AIRES</p><p style="text-align:justify"><strong>Dominio:</strong><strong>   </strong>[Acta:Dominio.Vehiculo]   <strong>Marca y modelo de vehículo:</strong>   [Acta:Actividad]  /   [Acta:Actividad]</p><p style="text-align:justify"><strong>Disposición legal infringida:   Art.  </strong> [Acta:Infracciones] Ley Nacional de Tránsito N° 24.449 (adherida por Ley Provincia N° 13.927).</p><p style="text-align:justify">Notifico a Ud., por medio de la presente que en el <strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>] </strong>la Sra. Directora de Faltas de la Municipalidad de Malvinas Argentinas, el día [System:TEXTOFECHA] ha dictado <strong>DISPOSICIÓN </strong><strong>N°</strong><strong> [Completar:N° de disposición]</strong>la que en su parte pertinente reza: &quot;Los Polvorines, [System:TEXTOFECHA]. - <strong>SEGUNDO: </strong>HACER efectiva la entrega del vehículo identificado como tipo <strong>[Completar:Identificado como tipo]</strong>marca<strong> [Completar:Como tipo marca]</strong>modelo<strong> [Completar:Tipo marca modelo]</strong>dominio <strong>[</strong><strong>Acta:Dominio.Vehiculo</strong><strong>] </strong>al <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>], DNI </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong>, en su carácter de <strong>TITULAR DE DOMINIO</strong> conforme <strong>CÉDULA DE IDENTIFICACIÓN DE VEHÍCULOS CONTROL [Completar:De vehículos control]</strong><strong>[Completar:De vehículos control]</strong>, titular de licencia de conducir N° [Acta:Nro.Documento], expedida por la Municipalidad de <strong>[Completar:Municipalidad]</strong>, con fecha de otorgamiento <strong>[Completar:Fecha de otorgamiento:fecha]</strong> - fecha de vencimiento <strong>[Completar:Fecha de vencimiento:fecha]</strong>, clase habilitante, en vigencia<strong>.&quot; (Fdo.) Dra. María Elena </strong><strong>Vivoda</strong><strong>, </strong><strong>Directora</strong><strong> de Faltas. -</strong></p><p style="text-align:center"><strong>QUEDA UD. DEBIDAMENTE NOTIFICADO/A.</strong></p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'CEDULA_POR_AUSENCIA_DE_DIRECTORA' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p><strong>Declaración Jurada de Constitución de Domicilio electrónico</strong></p><p style="text-align:center"><strong>CÓDIGO DE FALTAS</strong></p><p style="text-align:justify"><strong>Acta</strong><strong>:  [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify"><strong>Fecha:</strong><strong>   [</strong><strong>System:FECHA</strong><strong>]</strong></p><p style="text-align:justify"><strong>Nombre y Apellido: [</strong><strong>Acta:Titular</strong><strong>]</strong></p><p style="text-align:justify"><strong>DNI: [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong></p><p style="text-align:justify"><strong>Carácter:  </strong></p><p style="text-align:justify">Solicito que en los términos del artículo 11 de la ordenanza 16/96 conforme ordenanza 2601/24, las notificaciones que deban practicarse en las presentes actuaciones sean efectuadas al siguiente domicilio electrónico:</p><p style="text-align:justify">--------------------------------------------------@-------------------------------------------- que constituyo a tal efecto. </p><p style="text-align:justify">Asimismo, <strong>DECLARO BAJO JURAMENTO</strong> que consideraré válidas y suficientes a todos los efectos legales las notificaciones que en él se practiquen, considerando constancia de notificación fehaciente, a la fecha en que según los sistemas el correo ha sido abierto o a partir del primer día hábil de la semana siguiente a la emisión del mismo, corriendo desde ese momento los plazos procesales.</p><p style="text-align:center"><strong>[Completar:Los plazos procesales]</strong></p><p style="text-align:center"><strong>Firma</strong></p><p style="text-align:justify"><strong>Certifico que la firma que antecede fue puesta ante mi presencia y pertenece a la persona cuyos datos constan en el encabezamiento del formulario</strong></p><p><strong>Firma del funcionario</strong>: ______________________________________</p><p><strong>Legajo y aclaración</strong>: ________________________________________</p>' WHERE codigo = 'DD_JJ_DOMICILIO_ELECTRONICO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:justify">En el día de la fecha, por medio de la presente, se notifica al <strong>Sr. [</strong><strong>Acta:Titular</strong><strong>], [</strong><strong>Acta:TipoDocumento</strong><strong>] </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>], DISPOSICIÓN DE LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> [Completar:N° de disposición]</strong>de fecha [System:TEXTOFECHA] correspondiente al <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong>de fecha [Acta:Fecha] dictada por la Sra. Directora de Faltas de la Municipalidad de Malvinas Argentinas.</p><p style="text-align:justify">No siendo para más, previa lectura y ratificación de los datos consignados precedentemente, los comparecientes firman el presente de conformidad. Se cierra el acto.-</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTIFICA_LEVANTAMIENTO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:center"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:justify">En la ciudad de Los Polvorines, el día [System:TEXTOFECHA] siendo las [System:HORA] hs, se hizo presente ante la mesa de entradas de la Dirección de Faltas de la Municipalidad de Malvinas Argentinas el/la <strong>Sr./Sra. [</strong><strong>Acta:Titular</strong><strong>], DNI </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong> quién en ese acto se notifica personalmente del<strong> Fallo Administrativo </strong><strong>N°</strong><strong> ….</strong><strong>. </strong>de fecha [Completar:Fecha:fecha]</p><p style="text-align:justify">Déjese debida constancia en autos. -</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTIFICACION_FALLO_MDE' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:FECHA]</p><p style="text-align:center"><strong>DIRECCIÓN DE FALTAS</strong></p><p style="text-align:center"><strong>Ref. Acta </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] / Legajo </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:justify"><strong>Sr./Sra. [</strong><strong>Acta:Titular</strong><strong>], DNI </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong>, constituyendo domicilio en la calle <strong>[</strong><strong>Acta:Calle</strong><strong>]</strong> Nº <strong>[</strong><strong>Acta:Nro.Puerta</strong><strong>]</strong>, de la localidad de <strong>[</strong><strong>Acta:Localidad</strong><strong>]</strong>, partido de <strong>[</strong><strong>Acta:Partido</strong><strong>]</strong>, provincia de <strong>[</strong><strong>Acta:Provincia.Infractor</strong><strong>]</strong>, en el día de la fecha, comparezco ante la Dirección de Faltas de la Municipalidad de Malvinas Argentinas y me notificó personalmente del <strong>FALLO ADMINISTRATIVO </strong><strong>N°</strong>[Completar:N° de fallo]de fecha [Completar:Fecha:fecha]Dictado por el Sr. Intendente Municipal de Malvinas Argentinas, en concepto de multa por las infracciones detalladas en el <strong>Acta </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong>.</p><p style="text-align:justify">Se deja expresa constancia que conforme el Art. 84 de la Ley Nacional de Tránsito N° 24.449 que dice “El valor de la multa se determina en unidades fijas denominadas UF, cada una de las cuales equivale al menor precio de venta al público de un litro de nafta especial” y atento la Resolución 2025-9-GDEBA-SSPYSVMTRAGP de fecha 29 de agosto de 2025 el valor de la unidad fija actual es de $1.606, por lo tanto, el monto a abonar equivale a la suma de $ [Completar:Monto:moneda]</p><p style="text-align:justify">Asimismo, me comprometo a abonar los montos correspondientes a servicios varios en concepto de <strong>ESTADÍA</strong> de $ [Completar:Monto estadía:moneda]y de <strong>ACARREO</strong> de $[Completar:Monto acarreo:moneda]</p><p style="text-align:justify">En este acto, me comprometo a abonar en [Completar:Cantidad de cuotas:numero]cuotas mensuales y consecutivas, con un plazo para abonar la primera cuota dentro de los próximos [Completar:Días hábiles:numero]días hábiles. Juntamente con el monto anteriormente mencionado, y por única vez, abonaré la suma de <strong>PESOS CINCO MIL ($5.000) </strong>en concepto de sellado por actuaciones administrativas iniciadas, conforme lo establece la Ordenanza Fiscal y Tarifaria vigente.</p><p style="text-align:justify">Por último, tomó conocimiento en este acto y me notifico que la falta de pago en tiempo y forma producirá la extinción automática del presente plan, sin mediar notificación alguna por parte de esta Dirección y las actuaciones serán enviadas a la Dirección de Apremios para el inicio de las actuaciones judiciales pertinentes para efectivizar el cobro del monto adeudado. -</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'COMPROMISO_FALLO_TRANSITO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:FECHA]</p><p>Se deja constancia que con relación al Acta N° [Acta:Numero] obran actuaciones originadas en Expte N° 4132-[Completar:N° de expediente]</p><p>Conste. -</p>' WHERE codigo = 'EXPEDIENTE_COMPACTACION' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA] </p><p style="text-align:justify">Se deja constancia que, en el día de la fecha, se agregan a las actuaciones originadas en el <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong> copia de <strong>Expte</strong><strong>. Administrativo </strong><strong>N°</strong><strong> 4132-[Completar:N° de expediente]</strong>de fecha [Completar:Fecha:fecha] iniciado por <strong>[Completar:Fecha iniciado por]</strong>.</p><p style="text-align:justify">Conste. -</p>' WHERE codigo = 'EXPTE_ADMINISTRATIVO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong></p><p style="text-align:right"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>] </strong></p><p style="text-align:justify">Por medio de la presente se deja constancia que bajo <strong>Expte</strong><strong>. Administrativo </strong><strong>N°</strong><strong> 4132-</strong> [Completar:N° de expediente]tramita <strong>AFECTACIÓN AL USO MUNICIPAL</strong> del motovehículo descripto en el acta de la referencia. Conste. -</p>' WHERE codigo = 'NOTA_AFECTACION_AL_USO_MUNICIPAL' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:center"><strong>Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>]</strong></p><p style="text-align:center"><strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify">Por medio del presente se deja constancia que el presente legajo cuenta con antecedentes originados en <strong>Acta de Infracción </strong><strong>N°</strong><strong> [Completar:N° de acta]</strong>correspondiente a <strong>Legajo </strong><strong>N°</strong><strong> [Completar:N° de legajo], </strong>siendo agregado al mismo en el día de la fecha.</p><p style="text-align:justify">Conste. -</p>' WHERE codigo = 'NOTA_ANTECEDENTES' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right">Ref: Acta de Infracción N° [Acta:Numero]</p><p style="text-align:justify">Por medio de la presente se deja debidamente asentado que el rodado <strong>dominio [</strong><strong>Acta:Dominio.Vehiculo</strong><strong>] </strong>, mencionado en listado de vehículos afectados a proceso de compactación en Expte. Administrativo N° [Completar:N° de expediente]<strong>ACTUALMENTE</strong> se encuentra <strong>COMPACTADO</strong> atento <strong>Decreto </strong><strong>N°</strong><strong> [Completar:N° de decreto]de fecha [Completar:Fecha:fecha]</strong>dictado por el/la Sr./Sra. Intendente/a Municipal de Malvinas Argentinas.</p><p style="text-align:justify">Téngase presente y procédase al archivo de las actuaciones. -</p>' WHERE codigo = 'VEHICULOS_COMPACTADOS_DECRETO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: ACTA </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p><strong>Señor</strong></p><p><strong>Jefe de Mesa Gral. De Entradas y Archivo</strong></p><p><strong>Don Gustavo D. HEGOBURU</strong></p><p style="text-align:justify"><strong><u>S</u></strong><strong><u>/</u></strong><strong><u>D </u></strong></p><p style="text-align:justify">Remito a Ud. las presentes actuaciones para que las mismas sean caratuladas como <strong>“[</strong><strong>Acta:Titular</strong><strong>] S/LIQUIDACIÓN DE DEUDA ACTA DE INFRACCIÓN </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]”</strong>.<strong> </strong>Cumplido, pase a la Subsecretaría de Gobierno y Monitoreo Institucional para su conocimiento y posterior remisión a la Dirección de Apremios para la prosecución del trámite. </p><p style="text-align:justify">Se hace saber que el contraventor suscribió compromiso de pago para abonar en [Completar:Para abonar en]([Completar:Abonar en]) cuotas mensuales y consecutivas el Fallo Administrativo Nº [Completar:N° de fallo]Sin embargo, al día de la fecha no se ha cumplimentado en debida forma la obligación de pago asumida por el Sr[Completar:Nombre y apellido]-</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_APREMIOS_COMPR_DE_PAGO_NO_ABONO' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right"><strong>Ref.: ACTA </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong></p><p><strong>Señor</strong></p><p><strong>Jefe de Mesa Gral. De Entradas y Archivo</strong></p><p><strong>Don Gustavo D. HEGOBURU</strong></p><p style="text-align:justify"><strong><u>S</u></strong><strong><u>/</u></strong><strong><u>D</u></strong></p><p style="text-align:justify">Remito a Ud. las presentes actuaciones para que las mismas sean caratuladas como <strong>“[</strong><strong>Acta:Titular</strong><strong>] S/LIQUIDACIÓN DE DEUDA ACTA DE INFRACCIÓN </strong><strong>Nº</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]”</strong>.<strong> </strong>Cumplido, pase a la Subsecretaría de Gobierno y Monitoreo Institucional para su conocimiento y posterior remisión a la Dirección de Apremios para la prosecución del trámite.</p><p style="text-align:justify">Se hace saber que el contraventor suscribió un compromiso de pago para abonar en [Completar:Cantidad de cuotas:numero]cuotas mensuales y consecutivas el Fallo Administrativo Nº [Completar:N° de fallo], acreditándose únicamente el pago de [Completar:El pago de]([Completar:Pago de]) cuotas, siendo la última en fecha [Completar:Fecha:fecha] -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_APREMIOS_CON_COMP_DE_PAGO_CUOTAS' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref. Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right"><strong>Infractor: [</strong><strong>Acta:Titular</strong><strong>]</strong></p><p><strong>Al Depto. de </strong></p><p><strong>Licencias de Conducir de la </strong></p><p><strong>Municipalidad de [Completar:Municipalidad]</strong></p><p><strong>S_________/__________D</strong></p><p style="text-align:justify"><strong>VIVODA MARÍA ELENA</strong>, en mi carácter de Directora de Faltas de la Municipalidad de Malvinas Argentinas, ubicada en la calle San Martín N° 2670 – Local 2, Puerta 1 “Galería Libertador” de la ciudad de Los Polvorines, partido de Malvinas Argentinas, provincia de Buenos Aires, tengo el agrado de dirigirme a Ud. en relación al acta de referencia, a efectos de informar que esta dirección no procederá a la restitución de la licencia de conducir N° <strong>[</strong><strong>Acta:Nro.Documento</strong><strong>] </strong>atento su vencimiento operó el día [Completar:Fecha:fecha]y el conductor fue detenido por el operativo de control de documentación el pasado día [Acta:Fecha], por lo que llevaba <strong>[Completar:Lo que llevaba]</strong>circulando en infracción. En consecuencia, el funcionario de tránsito procedió retención conforme lo normado en el Art. 72 de la Ley Nacional de Tránsito N° 24.449, adherida por la provincia de Buenos Aires con la Ley Provincial N° 13.927, cuerpo normativo que contiene la misma disposición en su Art. 37.</p><p style="text-align:justify">El texto referido expresamente dice: <strong>ARTICULO 72. — RETENCION PREVENTIVA</strong>. La autoridad de comprobación o aplicación debe retener, dando inmediato conocimiento a la autoridad de juzgamiento: (…) <strong>b) </strong>A las licencias habilitantes, cuando: <strong>1. </strong>Estuvieren vencidas.</p><p style="text-align:justify">Acompañado copia certificada de <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong> y <strong>licencia de conducir </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>] </strong>expedida por la <strong>Municipalidad de [Completar:Municipalidad]</strong>con <strong>fecha de otorgamiento [Completar:Fecha de otorgamiento:fecha]</strong>y<strong> fecha de vencimiento [Completar:Fecha de vencimiento:fecha]</strong>. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_LICENCIA_VENCIDA' AND contenido_html NOT LIKE '%[Completar:%';
