UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:justify"><strong>DE: DIRECCIÓN DE FALTAS</strong></p><p style="text-align:justify"><strong>A: JUZGADO DE PAZ LETRADO – MALVINAS ARGENTINAS</strong></p><p style="text-align:justify"><strong>S____________________/____________________D</strong></p><p style="text-align:justify">Por medio de la presente me dirijo a Ud. en mi carácter de Directora de Faltas de la Municipalidad de Malvinas Argentinas, a fin de remitir las actuaciones labradas con relación al <strong>Acta de Infracción/Contravención </strong><strong>N°</strong><strong> [Completar:N° de acta]</strong> de fecha [Completar:Fecha:fecha], conforme <strong>RESOLUCIÓN </strong><strong>N°</strong><strong> …</strong><strong>[Completar:N° de resolución]</strong><strong>. </strong>de fecha [Completar:Fecha:fecha]</p><p style="text-align:justify">Sin otro particular, saluda atentamente. -</p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'JUZGADO_DE_PAZ' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong>Ref.: Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:right"><strong>Infractor: [</strong><strong>Acta:Titular</strong><strong>]</strong></p><p style="text-align:justify"><strong>DE: DIRECCIÓN A FALTAS</strong></p><p style="text-align:justify"><strong>A: DIRECCIÓN GENERAL DE SEGURIDAD VIAL Y TRANSPORTE</strong></p><p style="text-align:justify">Tengo el agrado de dirigirme a Ud. con relación al acta de la referencia atento en el día de la fecha se dictó la <strong>DISPOSICIÓN DE LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> [Completar:N° de disposición]</strong>correspondiente al <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] – Dominio [</strong><strong>Acta:Dominio.Vehiculo</strong><strong>]</strong>. Sin embargo, de los registros obrantes en la dependencia a mi cargo se constató que medió error involuntario al asignarse el número de disposición mencionado anteriormente toda vez que ya había sido asignado a otro acto administrativo.</p><p style="text-align:justify">Por ello, en este acto informo a Ud. que el número correcto resulta ser [Completar:Correcto resulta ser], Acompaño copia certificada de <strong>DISPOSICIÓN LEVANTAMIENTO DE SECUESTRO </strong><strong>N°</strong><strong> [Completar:N° de disposición]-</strong></p><p style="text-align:center"><strong>DF</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTA_A_SEG_VIAL_RECTIFICA_N_DE_DISP' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:right">Los Polvorines, [System:TEXTOFECHA]</p><p style="text-align:right"><strong><u>Ref.</u></strong><strong> Legajo </strong><strong>N°</strong><strong> [</strong><strong>Acta:Expediente</strong><strong>] - Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p style="text-align:justify">En el día de la fecha, siendo las [Completar:Hora]hs. por medio de la presente se deja expresa constancia que se hace entrega al <strong>Sr./Sra.  [</strong><strong>Acta:Titular</strong><strong>], D.N.I. </strong><strong>N°</strong><strong> [</strong><strong>Acta:Nro.Documento</strong><strong>]</strong>, la documentación que a continuación se detalla, a saber:</p><p style="text-align:justify">Licencia de conducir N° [Completar:N° de licencia]expedida por la Municipalidad de [Completar:Municipalidad], con fecha de otorgamiento [Completar:Fecha de otorgamiento:fecha]- fecha de vencimiento [Completar:Fecha de vencimiento:fecha]</p><p>Cédula de Identificación de Vehículos Control N° [Completar:Número]</p><p style="text-align:justify">Déjese debida constancia en autos de su retiro. Fecho. Conste. -</p><p style="text-align:justify"><strong>Firma: __________________________________________________</strong></p><p style="text-align:justify"><strong>Aclaración: ______________________________________________</strong></p><p style="text-align:justify"><strong>D.N.I. </strong><strong>Nº</strong><strong>: _______________________________________________</strong></p><p style="text-align:justify"><strong>Teléfono de contacto: _____________________________________</strong></p><p><strong>Constituyo domicilio electrónico: ___________________________</strong></p>' WHERE codigo = 'NOTA_ENTREGA_DOC_LIC_Y_CED' AND contenido_html NOT LIKE '%[Completar:%';
UPDATE plantilla SET contenido_html = '<p style="text-align:center"><strong><u>NOTIFICACION DE DISPOSICIÓN</u></strong></p><p><strong>Sr./Sra.:</strong><strong> </strong>  [Acta:Titular]          <strong>Disposición </strong><strong>N°</strong> [Completar:N° de disposición]</p><p><strong>Domicilio:</strong><strong>   </strong>[Acta:Calle]   <strong>N°</strong><strong>   </strong>[Acta:Nro.Puerta]</p><p><strong>Legajo </strong><strong>N°</strong><strong>   [</strong><strong>Acta:Expediente</strong><strong>]          Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>]</strong></p><p><strong>Localidad  /</strong><strong>  Partido:</strong><strong>   </strong>[Acta:Localidad]   /  [Acta:Partido]      <strong>Provincia:</strong><strong>   </strong>[Acta:Provincia.Infractor]</p><p><strong>Dependencia:   SUBSECRETARÍA DE TRÁNSITO Y BROMATOLOGÍA</strong></p><p style="text-align:justify">Se notifica a Ud. por la presente cédula que en el <strong>Acta de Infracción </strong><strong>N°</strong><strong> [</strong><strong>Acta:Numero</strong><strong>] </strong>que tramita ante la Dirección de Faltas de la Municipalidad de Malvinas Argentinas, se ha dictado la <strong>Disposición </strong><strong>N°</strong><strong> [Completar:N° de disposición]</strong>cuya copia se adjunta. -</p><p style="text-align:center"><strong>QUEDA UD. DEBIDAMENTE NOTIFICADO/A.</strong></p><p style="text-align:center"><strong>Dra. María Elena </strong><strong>Vivoda</strong></p><p style="text-align:center"><strong>Directora de Faltas</strong></p><p style="text-align:center"><strong>Municipalidad de Malvinas Argentinas</strong></p>' WHERE codigo = 'NOTIFICACION_DISPOSICION_TRANSITO' AND contenido_html NOT LIKE '%[Completar:%';

